package com.jobportal.config;
import com.jobportal.entity.*; import com.jobportal.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataSeeder{
 @Bean CommandLineRunner seed(UserRepository users,JobRepository jobs,PasswordEncoder encoder){return args->{if(users.count()>0)return;User r=new User();r.setName("Demo Recruiter");r.setEmail("recruiter@jobportal.local");r.setPassword(encoder.encode("Recruiter@123"));r.setRole(Role.RECRUITER);users.save(r);User c=new User();c.setName("Demo Candidate");c.setEmail("candidate@jobportal.local");c.setPassword(encoder.encode("Candidate@123"));c.setRole(Role.CANDIDATE);users.save(c);String[][] data={{"Java Spring Boot Developer","TechNova","Java, Spring Boot, REST, MySQL, JPA","Hyderabad"},{"React Frontend Developer","CloudWorks","React, Vite, JavaScript, Axios, HTML, CSS","Remote"},{"Full Stack Engineer","Innovate Labs","Java, Spring Boot, React, MySQL, Docker, JWT","Bengaluru"},{"AI/ML Engineer","Aster AI","Python, LLM, RAG, embeddings, vector search","Remote"}};for(String[] x:data){Job j=new Job();j.setRecruiter(r);j.setTitle(x[0]);j.setCompany(x[1]);j.setRequiredSkills(x[2]);j.setDescription("Build production features, collaborate with engineers and deliver reliable software. Strong communication and problem-solving skills expected.");j.setLocation(x[3]);j.setEmploymentType("FULL_TIME");j.setMinExperience(0);jobs.save(j);}};}
}
